#!/usr/bin/env node
/**
 * Generates a static index.html for every non-dynamic route so
 * Cloudflare Pages can serve them directly without relying on _redirects.
 *
 * Each generated file gets its own route-specific <title>, <meta description>,
 * og:title, og:description, og:url, og:image, canonical link, <h1>, and a
 * WebPage JSON-LD schema injected from the corresponding TSX source file --
 * so crawlers and AI search engines see the correct content in raw HTML,
 * not just after JS loads.
 *
 * TanStack Router flat-file naming:
 *   about.tsx                    -> /about.html
 *   compare.index.tsx            -> /compare.html
 *   compare.quickbridge-vs-x.tsx -> /compare/quickbridge-vs-x.html
 *   s.$id.tsx                    -> skipped (dynamic)
 *   __root.tsx                   -> skipped (layout)
 *   index.tsx                    -> skipped (already dist/client/index.html)
 */
import { readdir, readFile, mkdir, writeFile } from "node:fs/promises";
import { resolve, join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROUTES_DIR = resolve(__dirname, "../src/routes");
const DIST_DIR   = resolve(__dirname, "../dist/client");

/**
 * Extract the value of a string constant from TSX source.
 * Handles both:
 *   const FOO = "value"
 *   const FOO =
 *     "value"
 * and single-quote variants.
 */
function extractConst(src, ...names) {
  for (const name of names) {
    const re = new RegExp(
      `const\\s+${name}\\s*=\\s*(?:\\n\\s*)?["'\`]([^"'\`\\n]+)["'\`]`
    );
    const m = src.match(re);
    if (m) return m[1].trim();
  }
  return null;
}

function esc(str) {
  return str
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function buildWebPageJsonLd(title, description, url) {
  const schema = {
    "@context": "https://schema.org",
    "@type": "WebPage",
    name: title,
    description: description,
    url: url,
    inLanguage: "en",
    publisher: {
      "@type": "Organization",
      name: "QuickBridge",
      url: "https://quickbridge.app",
    },
  };
  return JSON.stringify(schema);
}

function injectMeta(html, { title, description, url, ogImage }) {
  let out = html;

  if (title) {
    out = out.replace(
      /<title>[^<]*<\/title>/,
      `<title>${esc(title)}</title>`
    );
  }

  if (description) {
    out = out.replace(
      /<meta name="description"[^>]*\/>/,
      `<meta name="description" content="${esc(description)}" />`
    );
  }

  // Strip any OG meta tags and canonical link already present in the shell
  // (these come from index.html homepage defaults) so we don't get duplicates.
  out = out.replace(/<meta property="og:[^"]*"[^>]*\/>\n?/g, "");
  out = out.replace(/<meta property="og:[^"]*"[^>]*>\n?/g, "");
  out = out.replace(/<link rel="canonical"[^>]*\/>\n?/g, "");
  out = out.replace(/<link rel="canonical"[^>]*>\n?/g, "");

  // Build the block of route-specific tags to inject just before </head>
  const headTags = [];
  if (title)       headTags.push(`    <meta property="og:title" content="${esc(title)}" />`);
  if (description) headTags.push(`    <meta property="og:description" content="${esc(description)}" />`);
  if (url) {
    headTags.push(`    <meta property="og:url" content="${esc(url)}" />`);
    headTags.push(`    <link rel="canonical" href="${esc(url)}" />`);
  }
  if (ogImage) headTags.push(`    <meta property="og:image" content="${esc(ogImage)}" />`);

  // Inject a WebPage JSON-LD schema so crawlers see valid structured data
  // without running JavaScript. React injects the full rich schemas at runtime.
  if (title && url) {
    const jsonLd = buildWebPageJsonLd(title, description || "", url);
    headTags.push(`    <script type="application/ld+json">${jsonLd}</script>`);
  }

  if (headTags.length) {
    out = out.replace("</head>", headTags.join("\n") + "\n  </head>");
  }

  // Inject an H1 into the pre-rendered body shell so crawlers see a heading.
  // React replaces the root div contents when JS loads, rendering its own H1.
  if (title) {
    out = out.replace(
      '<div id="root"></div>',
      `<div id="root"><h1>${esc(title)}</h1></div>`
    );
  }

  return out;
}

// --- build route list ---
const files = await readdir(ROUTES_DIR);
let indexHtml = await readFile(join(DIST_DIR, "index.html"), "utf-8");

// --- patch homepage (index.html is generated by Vite, not by this script) ---
// Inject H1 + WebPage JSON-LD into the homepage shell so crawlers see them.
{
  const homeSrc = await readFile(join(ROUTES_DIR, "index.tsx"), "utf-8");
  const homeTitle       = extractConst(homeSrc, "HOME_TITLE", "PAGE_TITLE");
  const homeDescription = extractConst(homeSrc, "HOME_DESCRIPTION", "PAGE_DESCRIPTION");
  const homeUrl         = extractConst(homeSrc, "HOME_URL", "PAGE_URL");

  if (homeTitle && homeUrl) {
    const jsonLd = buildWebPageJsonLd(homeTitle, homeDescription || "", homeUrl);
    const jsonLdTag = `    <script type="application/ld+json">${jsonLd}</script>`;
    if (!indexHtml.includes('type="application/ld+json"')) {
      indexHtml = indexHtml.replace("</head>", jsonLdTag + "\n  </head>");
    }
    if (!indexHtml.includes('<h1>')) {
      indexHtml = indexHtml.replace(
        '<div id="root"></div>',
        `<div id="root"><h1>${esc(homeTitle)}</h1></div>`
      );
    }
    await writeFile(join(DIST_DIR, "index.html"), indexHtml);
    console.log(`  patched /index.html -- "${homeTitle.slice(0, 55)}"`);
  }
}

const routes = [];
for (const file of files) {
  if (!file.endsWith(".tsx")) continue;
  const name = file.replace(/\.tsx$/, "");
  if (name.startsWith("__")) continue;
  if (name.includes("$"))    continue;
  if (name === "index")      continue;

  const parts = name.split(".");
  if (parts[parts.length - 1] === "index") parts.pop();
  routes.push({ route: "/" + parts.join("/"), file });
}

// --- generate ---
let count = 0;
for (const { route, file } of routes) {
  const src = await readFile(join(ROUTES_DIR, file), "utf-8");

  const title       = extractConst(src, "PAGE_TITLE", "HOME_TITLE", "JOIN_TITLE");
  const description = extractConst(src, "PAGE_DESCRIPTION", "HOME_DESCRIPTION", "JOIN_DESCRIPTION");
  const url         = extractConst(src, "PAGE_URL", "HOME_URL", "JOIN_URL");
  const ogImage     = extractConst(src, "PAGE_OG_IMAGE", "HOME_OG_IMAGE");

  const html = injectMeta(indexHtml, { title, description, url, ogImage });

  const dest = join(DIST_DIR, route + ".html");
  await mkdir(dirname(dest), { recursive: true });
  await writeFile(dest, html);
  console.log(`  generated ${route}.html${title ? ` -- "${title.slice(0, 55)}"` : ""}`);
  count++;
}

console.log(`\n✓ ${count} static route files written to dist/client/`);
